import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between start and end nodes using Dijkstra's algorithm.

    Args:
        edges: List of tuples (from_node, to_node, weight) representing one-way streets
        start: Starting node
        end: Destination node

    Returns:
        A tuple (distance, path) where distance is the total distance and path is a list of nodes
        If no path exists: (None, None)

    Raises:
        ValueError: If any edge has negative weight
    """
    # Handle start == end case
    if start == end:
        return (0, [start])

    # Build adjacency list and validate for negative weights
    graph = {}
    valid_nodes = set()

    for from_node, to_node, weight in edges:
        # Track all nodes for validation purposes
        valid_nodes.add(from_node)
        valid_nodes.add(to_node)

        if weight < 0:
            raise ValueError("Negative edge weight detected")

        if from_node not in graph:
            graph[from_node] = {}
        graph[from_node][to_node] = weight

    # Check if start and end nodes are valid
    if start not in valid_nodes or end not in valid_nodes:
        return (None, None)

    # If start is not in graph with outgoing edges, no path possible
    if start not in graph:
        return (None, None)

    # Dijkstra's algorithm
    distances = {start: 0}
    previous = {start: None}

    # Priority queue: (distance, node)
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        # Skip if we've found a shorter path already
        if current_dist > distances.get(current_node, float('inf')):
            continue

        # If we reached the target
        if current_node == end:
            break

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node].items():
                distance = current_dist + weight
                if neighbor not in distances or distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(pq, (distance, neighbor))

    # Check if end was reached
    if end not in distances:
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous[current]

    path.reverse()
    return (distances[end], path)
